Starting app.R
library(shiny)
library(tidyverse)

ui &lt;- fluidPage(
  titlePanel("Old Faithful Geyser Explorer"),
  sidebarLayout(
    sidebarPanel(
      selectInput("variable",
                  "Variable to display:",
                  choices = c("Waiting Time"  = "waiting",
                              "Eruption Time" = "eruptions"))
    ),
    mainPanel(
      plotOutput("histPlot")
    )
  )
)

server &lt;- function(input, output) {
  output$histPlot &lt;- renderPlot({
    x_label &lt;- if (input$variable == "waiting") {
      "Waiting Time (minutes)"
    } else {
      "Eruption Time (minutes)"
    }
    faithful |&gt;
      ggplot(aes(x = .data[[input$variable]])) +
      geom_histogram(bins = 30, fill = "steelblue", color = "white") +
      theme_minimal() +
      labs(x = x_label, y = "Count",
           title = paste("Distribution of", x_label))
  })
}

shinyApp(ui = ui, server = server)

